        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "additionalProperties": {
                    "type": "object",
                    "additionalProperties": {
                      "$ref": "#/components/schemas/Hours"
                    }
                  }
                },
                "examples": {
                  "GetMarketHour": {
                    "$ref": "#/components/examples/GetMarketHour"
                  }
                }
              }
            },
            "headers": {
              "Schwab-Client-CorrelId": {
